1: // DOCUMENTS: pure presentation model — engine snapshot in, labels and bar
2: // geometry out. No DOM here: this is what the unit suite pins; panel.js and
3: // render.js own all DOM writes. Stage-6 hop sentences live in
4: // model-stage6.js (guard-file-size split).
5: import { stage6Sentences } from './model-stage6.js';
6: export const TICK_MS = 100;
7: const QUEUE_BAR_SATURATION = 20; // bar reads full at 20 queued requests
8: // Total hops per stage's trace shape (trace.js, trace-stage6.js and
9: // engine.traceHop agree). Stage 6's hosted shape is 9: the DNS ask + answer
10: // plus the stage-5 chain's wire hops (its emit hop is the browser's
11: // composition, not a wire frame).
12: const TOTAL_HOPS = { 1: 4, 2: 5, 3: 6, 4: 7, 5: 8, 6: 9 };
13: 
14: const HOP_START_SENTENCE = 'Idle — type a path and click Go or Step 1 Hop ->';
15: 
16: function fillPercent(depth) {
17:   return `${Math.min(100, Math.round((depth / QUEUE_BAR_SATURATION) * 100))}%`;
18: }
19: 
20: // One hop-sentence set per Stage 5 trace shape — async POST /jobs vs the
21: // synchronous cache/database story. Eight bare sentences with no "Hop n/8: "
22: // prefix: stage 5 and stage 6's host-less trace wrap them identically (the
23: // host-less counter-example renders byte-identically), and stage 6's hosted
24: // shape renumbers the tail behind its DNS prelude.
25: export function stage5ChainParts(snapshot, from, serverAddress) {
26:   const t = snapshot.trace ?? {};
27:   const target = t.targetServer ?? '10.11';
28:   if (t.asyncJob) {
29:     const worker = snapshot.workerQueue?.workerAddress ?? '10.41';
30:     return [
31:       `Browser (${from}) emits "${t.request}"`,
32:       `Network (10.x) routes to LoadBalancer (${serverAddress})`,
33:       `LoadBalancer (${serverAddress}) -> ${target} queue`,
34:       `WebServer (${target}) enqueues job to WorkerQueue (10.40)`,
35:       `WebServer (${target}) -> "202 Accepted"`,
36:       `Network delivers 202 response to ${from}`,
37:       `Browser (${from}) received and displayed 202 Accepted`,
38:       `Worker (${worker}) processed job and committed to Database (10.30)`,
39:     ];
40:   }
41:   // Requests served synchronously keep the Stage 4 cache/database story;
42:   // the worker does not see them, so the tail hop reads idle.
43:   const db = snapshot.database ?? {};
44:   const primary = db.primaryAddress ?? '10.30';
45:   const replica = db.replicaAddress ?? '10.31';
46:   const lag = db.replicationLagTicks ?? 3;
47:   const dbOp =
48:     t.dbOp === 'WRITE'
49:       ? `Database WRITE @ Primary (${primary}) — replica lags ${lag}t`
50:       : t.dbOp === 'SELECT' && t.dbStale
51:         ? `Database SELECT @ Replica (${replica}) — STALE (lag ${lag}t)`
52:         : t.dbOp === 'SELECT'
53:           ? `Database SELECT @ Replica (${replica}) — fresh`
54:           : `Database SKIP — warm cache HIT (${snapshot.cache?.address ?? '10.20'})`;
55:   return [
56:     `Browser (${from}) emits "${t.request}"`,
57:     `Network (10.x) routes to LoadBalancer (${serverAddress})`,
58:     `LoadBalancer (${serverAddress}) -> ${target} queue`,
59:     dbOp,
60:     `WebServer (${target}) -> "${t.response}" (cache ${t.cacheStatus})`,
61:     `Network delivers ${t.status} response to ${from}`,
62:     `Browser (${from}) received and displayed ${t.status}`,
63:     `Worker (${workerAddressOf(snapshot)}) idle — no async jobs in this trace`,
64:   ];
65: }
66: 
67: const workerAddressOf = (snapshot) => snapshot.workerQueue?.workerAddress ?? '10.41';
68: 
69: export const withHopPrefix = (parts, total) => parts.map((p, i) => `Hop ${i + 1}/${total}: ${p}`);
70: 
71: // Stage 6 composes its sentences in model-stage6.js: the two DNS prelude
72: // sentences plus one of the three hosted shapes behind the answer (plain
73: // subnet-10 chain, Stage-6b CDN chain, or the NX refusal), or the
74: // byte-identical host-less stage-5 story. An NX answer ends the trace at
75: // hop 2 — the browser renders the refusal card and no GET appears anywhere
76: // downstream (pinned counter-example in test/panel/model-stage6.test.js).
77: 
78: // One hop-status sentence per hop, in hop order, for each stage's trace
79: // shape: 4 hops in Stage 1 (emit, route, serve, render), 5 in Stage 2 (LB
80: // round-robin pick), 6 in Stage 3 (cache check, then response emit), 7 in
81: // Stage 4 (the database hop after the cache check), 8 in Stage 5, and the
82: // stage-6 shapes above.
83: function hopSentences(stage, snapshot, from, serverAddress) {
84:   const t = snapshot.trace ?? {};
85:   const target = t.targetServer ?? '10.11';
86:   if (stage === 6) return stage6Sentences(snapshot, from, serverAddress);
87:   if (stage === 5) {
88:     return withHopPrefix(stage5ChainParts(snapshot, from, serverAddress), 8);
89:   }
90:   if (stage === 4) {
91:     const db = snapshot.database ?? null;
92:     const primary = db?.primaryAddress ?? '10.30';
93:     const replica = db?.replicaAddress ?? '10.31';
94:     const lag = db?.replicationLagTicks ?? 3;
95:     const dbSentence =
96:       t.dbOp === 'WRITE'
97:         ? `Hop 5/7: Database WRITE @ Primary (${primary}) — replica lags ${lag}t`
98:         : t.dbOp === 'SELECT' && t.dbStale
99:           ? `Hop 5/7: Database SELECT @ Replica (${replica}) — STALE (lag ${lag}t)`
100:           : t.dbOp === 'SELECT'
101:             ? `Hop 5/7: Database SELECT @ Replica (${replica}) — fresh`
102:             : `Hop 5/7: Database SKIP — warm cache HIT (10.20)`;
103:     return [
104:       `Hop 1/7: Browser (${from}) emits "${t.request}"`,
105:       `Hop 2/7: Network (10.x) routes to LoadBalancer (${serverAddress})`,
106:       `Hop 3/7: LoadBalancer (${serverAddress}) -> ${target} queue`,
107:       `Hop 4/7: WebServer (${target}) checks Cache (10.20) — ${t.cacheStatus}`,
108:       dbSentence,
109:       `Hop 6/7: WebServer (${target}) -> "${t.response}" (cache ${t.cacheStatus})`,
110:       `Hop 7/7: Browser (${from}) rendered ${t.status}`,
111:     ];
112:   }
113:   if (stage === 3) {
114:     return [
115:       `Hop 1/6: Browser (${from}) emits "${t.request}"`,
116:       `Hop 2/6: Network (10.x) routes to LoadBalancer (${serverAddress})`,
117:       `Hop 3/6: LoadBalancer (${serverAddress}) -> ${target} queue`,
118:       `Hop 4/6: WebServer (${target}) checks Cache (10.20) — ${t.cacheStatus}`,
119:       `Hop 5/6: WebServer (${target}) -> "${t.response}" (cache ${t.cacheStatus})`,
120:       `Hop 6/6: Browser (${from}) rendered ${t.status}`,
121:     ];
122:   }
123:   if (stage === 2) {
124:     return [
125:       `Hop 1/5: Browser (${from}) emits "${t.request}"`,
126:       `Hop 2/5: Network (10.x) routes to LoadBalancer (${serverAddress})`,
127:       `Hop 3/5: LoadBalancer (${serverAddress}) -> ${target} queue`,
128:       `Hop 4/5: WebServer (${target}) -> "${t.response}"`,
129:       `Hop 5/5: Browser (${from}) rendered ${t.status}`,
130:     ];
131:   }
132:   return [
133:     `Hop 1/4: Browser (${from}) emits "${t.request}"`,
134:     `Hop 2/4: Network (10.x) routes to ${serverAddress} queue`,
135:     `Hop 3/4: WebServer (${serverAddress}) -> "${t.response}"`,
136:     `Hop 4/4: Browser (${from}) rendered ${t.status}`,
137:   ];
138: }
