31:     ['example.com', '10.1'],
32:     ['cd.example.com', '20.1'],
33:   ]); // authoritative table
34:   const ledger = new Map(); // name -> { name, target, writtenAtTick, expiresAtTick }
35:   let lookups = 0;
36:   let cachedHits = 0;
37:   let authoritative = 0;
38:   let lastLookup = null;
