### compare.js (new, DOM-only)

```js
// DOCUMENTS: the compare tray (B-5) — a JS-built auto-pair diff inside the
// .log-card: the two most recent completed trace runs, hop-aligned rows of
// verbatim journey-log entry texts. The tray never mints or rewrites hop
// frames (DL-1/DL-3): every cell is a stored entry's text or the em-dash for
// an exhausted side. Pure slot/align logic lives in model.js; this module is
// DOM-bound only (lazy-lookup precedent: renderDnsHud, stage6-registry.js).
import { alignCompareRows, nextCompareSlots } from './model.js';
import { getRunEntries } from './render.js';

let slots = { a: null, b: null };
let injected = false;

function ensureTray() {
  if (injected) return;
  injected = true;
  const card = document.querySelector('.log-card');
  const tray = document.createElement('div');
  tray.id = 'compare-tray';
  tray.dataset.testid = 'compare-tray';
  tray.hidden = true; // hidden until a full pair exists (consistent choice)
  const headline = document.createElement('p');
  headline.id = 'compare-headline';
  headline.dataset.testid = 'compare-headline';
  headline.className = 'compare-headline';
  const rows = document.createElement('ol');
  rows.id = 'compare-rows';
  rows.dataset.testid = 'compare-rows';
  rows.className = 'compare-rows';
  tray.append(headline, rows);
  card.append(tray);
}

// PINS: the snapshot at completion — entries copied here survive later
// JOURNEY_CAP trims and relabels of the live journey log.
export function pushCompareRun({ run, label, entries }) {
  ensureTray();
  const snapshot = {
    run,
    label,
    hops: entries.length,
    entries: entries.map((entry) => ({ ...entry })),
  };
  const next = nextCompareSlots(slots, snapshot);
  if (!next.changed) return;
  slots = { a: next.a, b: next.b };
  renderTray();
}

export function clearCompare() {
  slots = { a: null, b: null };
  renderTray();
}

// CHECKS: hidden while the pair is incomplete/empty (zero or one stored run)
// — the tray renders no rows rather than a half comparison.
function renderTray() {
  const tray = document.getElementById('compare-tray');
  if (!tray) return;
  tray.hidden = !(slots.a && slots.b);
  const headline = ...;
  const rows = ...;
  if (!(slots.a && slots.b)) { headline.textContent=''; rows.replaceChildren(); return; }
  headline.textContent = `${slots.a.hops} vs ${slots.b.hops} hops · ${slots.a.label} vs ${slots.b.label}`;
  rows.replaceChildren(
    ...alignCompareRows(slots.a, slots.b).map(({ n, left, right }) => {
      const li = document.createElement('li');
      li.className = 'compare-row';
      const nSpan..., leftSpan..., rightSpan...;
      ...
      return li;
    }),
  );
}

// CHECKS: the label is the run's own descriptor from the trace snapshot —
// method + typed path; stage 6 hosted runs carry the host separately, so it
// rejoins here (GET example.com/about), host-less runs read GET /about.
export function compareRunLabel(trace) {
  const path = trace?.path ?? '';
  return trace?.host ? `${trace.method} ${trace.host}${path}` : `${trace.method} ${path}`;
}
```

