.exchange-line {
  margin: 0.4rem 0 0.6rem;
  font-family: var(--mono);
  font-variant-numeric: tabular-nums;
  font-size: 0.8rem;
}

/* Compare tray (B-5 brief): auto-pair diff of the two most recent completed
   trace runs, injected by compare.js inside .log-card. Rows match
   .journey-entry's mono styling; protocol strings ride var(--mono). Rows
   wrap (overflow-wrap, the .journey-entry rule) so the tray never overflows
   the card. */
.compare-tray {
  margin-top: 0.6rem;
  border-top: 1px solid var(--border);
  padding-top: 0.5rem;
}

.compare-tray[hidden] {
  display: none;
}

.compare-headline {
  margin: 0 0 0.4rem;
  font-size: 0.72rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-muted);
}

.compare-rows {
  margin: 0;
  padding: 0;
  list-style: none;
  max-height: 12rem;
  overflow: auto;
}

.compare-row {
  display: grid;
  grid-template-columns: 2.5rem 1fr 1fr;
  gap: 0.5rem;
  padding: 0.25rem 0;
  border-bottom: 1px solid var(--border);
  font-family: var(--mono);
  font-variant-numeric: tabular-nums;
  font-size: 0.72rem;
  color: var(--text-muted);
  overflow-wrap: anywhere;
}

.compare-row .compare-cell {
  min-width: 0;
}

.compare-row .compare-empty {
  color: var(--text-muted);
}

