9: // Serve from the front of the target's queue until the trace's own
10: // request (isYou) comes back, or the queue runs dry this tick.
11: export function drainUntilYou(targetServer, getTick) {
12:   for (;;) {
13:     const batch = targetServer.step(getTick());
14:     const you = batch.find((item) => item.isYou);
15:     if (you || batch.length === 0) return you;
16:   }
17: }
18: 
19: export function backendFor(servers, targetAddress) {
20:   return servers.find((s) => s.address === targetAddress) ?? servers[0];
21: }
22: 
23: export function serveInto(trace, you, onServe) {
24:   trace.response = you.response;
25:   trace.status = you.status;
26:   trace.body = you.body;
27:   trace.routeId = you.routeId;
28:   onServe(you);
29: }
